import React, { useState } from 'react';
import axios from 'axios';
import './App.css';

const BACKEND = "http://localhost:8000";

// Pre-loaded demo products for the UI
// Filenames MUST match exactly what's in backend/uploads/
const DEMO_PRODUCTS = [
  { id: 'lays', name: "Lay's Magic Masala", file: "lays.jpg" },
  { id: 'almonds', name: "Smoked Almonds", file: "almonds.jpg" },
  { id: 'lux_soap', name: "Lux Soap", file: "lux_soap.jpg" },
  { id: 'cura', name: "Cura Aamla Ras", file: "cura.jpg" },
  { id: 'natures_essence', name: "Nature's Essence Lotion", file: "natures_essence.jpg" },
  { id: 'dr_sheths', name: "Dr. Sheth's Serum", file: "dr_sheths.jpg" }
];

function App() {
  const [report, setReport] = useState(null);
  const [loading, setLoading] = useState(false);
  const [selectedProduct, setSelectedProduct] = useState(null);

  const handleProductSelect = async (product) => {
    setSelectedProduct(product);
    setLoading(true);
    setReport(null);

    try {
      // Fetch the image from backend/uploads
      const imageUrl = `${BACKEND}/uploads/${product.file}`;
      const response = await fetch(imageUrl);

      if (!response.ok) {
        throw new Error(
          `Image "${product.file}" not found in backend/uploads folder. ` +
          `Please add it with this exact name.`
        );
      }

      const blob = await response.blob();
      const file = new File([blob], product.file, { type: blob.type });

      const formData = new FormData();
      formData.append("file", file);

      const res = await axios.post(`${BACKEND}/api/analyze`, formData);
      setReport(res.data);
    } catch (err) {
      console.error("Full error:", err);
      const errorMsg =
        err.response?.data?.detail ||
        err.message ||
        "Unknown error occurred";
      alert(`Error: ${errorMsg}`);
    }
    setLoading(false);
  };

  const handleImageUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    setLoading(true);
    setReport(null);
    const formData = new FormData();
    formData.append("file", file);
    try {
      const res = await axios.post(`${BACKEND}/api/analyze`, formData);
      setReport(res.data);
    } catch (err) {
      console.error("Full error:", err);
      const errorMsg = err.response?.data?.detail || err.message;
      alert(`Error: ${errorMsg}`);
    }
    setLoading(false);
  };

  const getVerdictClass = (overall) => {
    if (!overall) return '';
    return overall.toLowerCase().replace(/\s+/g, '-');
  };

  return (
    <div className="app">
      <header>
        <h1>🇮🇳 Legal Metrology Compliance Checker</h1>
        <p>AI-assisted screening of packaged product labels</p>
      </header>

      <div className="demo-grid">
        <h3>Select a Demo Product:</h3>
        <div className="product-buttons">
          {DEMO_PRODUCTS.map(p => (
            <button
              key={p.id}
              onClick={() => handleProductSelect(p)}
              className={selectedProduct?.id === p.id ? 'active' : ''}
              disabled={loading}
            >
              {p.name}
            </button>
          ))}
        </div>
      </div>

      <div className="upload-section">
        <p>Or upload a new image (must match demo filenames):</p>
        <input
          type="file"
          accept="image/*"
          onChange={handleImageUpload}
          disabled={loading}
        />
      </div>

      {loading && <div className="loading">🔍 Analyzing... (OCR may take 5-10 seconds)</div>}

      {report && !loading && (
        <div className="results">
          <div className={`score-card ${getVerdictClass(report.overall)}`}>
            <div className="score">{report.score}/100</div>
            <div className="verdict">{report.overall}</div>
          </div>

          <div className="product-info">
            <h3>{report.product_name}</h3>
            <img
              src={`${BACKEND}${report.image_url}`}
              alt={report.product_name}
              className="product-image"
            />
          </div>

          <div className="extracted-fields">
            <h3>📋 Extracted Information</h3>
            {report.extracted_fields && Object.keys(report.extracted_fields).length > 0 ? (
              Object.entries(report.extracted_fields).map(([key, val]) => (
                <div key={key} className="field">
                  <strong>{key.replace('_', ' ')}:</strong>{' '}
                  {val?.value || 'Not detected'}
                  {val?.uncertain && (
                    <span className="uncertain-badge"> ⚠️ uncertain</span>
                  )}
                </div>
              ))
            ) : (
              <p>No fields extracted.</p>
            )}
          </div>

          <div className="rule-results">
            <h3>⚖️ Rule Check Results</h3>
            {report.violations && report.violations.length > 0 ? (
              report.violations.map((v, i) => (
                <div key={i} className="violation">
                  <span className="status-icon">🔴</span>
                  <div>
                    <strong>{v.field.replace('_', ' ')}:</strong> {v.reason}
                    <div className="citation">📜 {v.citation}</div>
                  </div>
                </div>
              ))
            ) : (
              <div className="compliant-msg">
                ✅ No violations found. This product appears compliant.
              </div>
            )}
            {report.notes && (
              <div className="notes">
                <strong>Note:</strong> {report.notes}
              </div>
            )}
          </div>
        </div>
      )}

      <footer>
        <small>
          ⚠️ AI-assisted screening tool. Final compliance decision rests with the
          authorized Legal Metrology inspector.
        </small>
      </footer>
    </div>
  );
}

export default App;
